export const viewerCss: string = "/*\n * Viewer chrome. Colors follow the deck theme: the plugin writes\n * data-presenit-theme and --presenit-viewer-hue on <html>, so the page\n * matches the slides from the first paint, before this Viewer script runs.\n */\n:root {\n    --presenit-viewer-hue: 210;\n    --presenit-aspect: 16 / 9;\n    --presenit-ui-backdrop: oklch(0.9 0.012 var(--presenit-viewer-hue));\n    --presenit-ui-panel: oklch(0.975 0.005 var(--presenit-viewer-hue));\n    --presenit-ui-raised: oklch(1 0 0);\n    --presenit-ui-surface: oklch(0.995 0.003 var(--presenit-viewer-hue) / 0.86);\n    --presenit-ui-text: oklch(0.25 0.02 var(--presenit-viewer-hue));\n    --presenit-ui-muted: oklch(0.47 0.02 var(--presenit-viewer-hue));\n    --presenit-ui-line: oklch(0.25 0.03 var(--presenit-viewer-hue) / 0.14);\n    --presenit-ui-hover: oklch(0.25 0.03 var(--presenit-viewer-hue) / 0.08);\n    --presenit-ui-accent: oklch(0.5 0.17 var(--presenit-viewer-hue));\n    --presenit-ui-accent-soft: oklch(0.5 0.17 var(--presenit-viewer-hue) / 0.13);\n    --presenit-ui-tip-bg: oklch(0.22 0.015 var(--presenit-viewer-hue) / 0.96);\n    --presenit-ui-tip-text: oklch(0.98 0.004 var(--presenit-viewer-hue));\n    --presenit-ui-scrim: oklch(0.2 0.02 var(--presenit-viewer-hue) / 0.45);\n    --presenit-ui-shadow:\n        0 1px 2px oklch(0.2 0.03 var(--presenit-viewer-hue) / 0.1),\n        0 10px 30px -6px oklch(0.2 0.03 var(--presenit-viewer-hue) / 0.25);\n    --presenit-ui-slide-shadow:\n        0 1px 2px oklch(0.2 0.03 var(--presenit-viewer-hue) / 0.08),\n        0 16px 48px -16px oklch(0.2 0.03 var(--presenit-viewer-hue) / 0.35);\n    color-scheme: light;\n    font-family:\n        system-ui,\n        -apple-system,\n        \"Segoe UI\",\n        \"Hiragino Sans\",\n        \"Noto Sans JP\",\n        sans-serif;\n    color: var(--presenit-ui-text);\n    background: var(--presenit-ui-backdrop);\n}\n:root[data-presenit-theme=\"dark\"] {\n    --presenit-ui-backdrop: oklch(0.11 0.008 var(--presenit-viewer-hue));\n    --presenit-ui-panel: oklch(0.17 0.01 var(--presenit-viewer-hue));\n    --presenit-ui-raised: oklch(0.21 0.012 var(--presenit-viewer-hue));\n    --presenit-ui-surface: oklch(0.23 0.014 var(--presenit-viewer-hue) / 0.84);\n    --presenit-ui-text: oklch(0.93 0.008 var(--presenit-viewer-hue));\n    --presenit-ui-muted: oklch(0.71 0.012 var(--presenit-viewer-hue));\n    --presenit-ui-line: oklch(1 0 0 / 0.12);\n    --presenit-ui-hover: oklch(1 0 0 / 0.1);\n    --presenit-ui-accent: oklch(0.78 0.12 var(--presenit-viewer-hue));\n    --presenit-ui-accent-soft: oklch(0.78 0.12 var(--presenit-viewer-hue) / 0.2);\n    --presenit-ui-tip-bg: oklch(0.95 0.006 var(--presenit-viewer-hue) / 0.97);\n    --presenit-ui-tip-text: oklch(0.2 0.015 var(--presenit-viewer-hue));\n    --presenit-ui-scrim: oklch(0 0 0 / 0.55);\n    --presenit-ui-shadow: 0 1px 2px oklch(0 0 0 / 0.3), 0 12px 32px -6px oklch(0 0 0 / 0.55);\n    --presenit-ui-slide-shadow: 0 16px 48px -12px oklch(0 0 0 / 0.6);\n    color-scheme: dark;\n}\nhtml,\nbody {\n    margin: 0;\n    min-height: 100%;\n}\nbody {\n    background: var(--presenit-ui-backdrop);\n}\nbutton {\n    font: inherit;\n    color: inherit;\n    cursor: pointer;\n}\n:focus-visible {\n    outline: 2px solid var(--presenit-ui-accent);\n    outline-offset: 2px;\n}\n[hidden] {\n    display: none !important;\n}\n.presenit-sr {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    margin: -1px;\n    padding: 0;\n    overflow: hidden;\n    clip-path: inset(50%);\n    white-space: nowrap;\n    border: 0;\n}\n.presenit-icon {\n    width: 20px;\n    height: 20px;\n    flex: none;\n    fill: none;\n    stroke: currentColor;\n    stroke-width: 2;\n    stroke-linecap: round;\n    stroke-linejoin: round;\n}\n\n/* Avoid a flash of the unscaled deck before the Viewer starts. If the script\n   never runs, the slides appear anyway after a short delay. */\n@media (scripting: enabled) {\n    html:not(.presenit-ready) #presenit-stage {\n        visibility: hidden;\n        animation: presenit-fallback 0s 2s forwards;\n    }\n}\n@keyframes presenit-fallback {\n    to {\n        visibility: visible;\n    }\n}\n\n/* ------------------------------------------------------------------ */\n/* Stage: the slide is as large as the window allows, with no space    */\n/* reserved for controls.                                             */\n/* ------------------------------------------------------------------ */\n.presenit-ready body {\n    height: 100dvh;\n    overflow: hidden;\n    overscroll-behavior: none;\n}\n.presenit-ready .presenit-layout {\n    display: flex;\n    height: 100dvh;\n}\n.presenit-ready .presenit-main {\n    flex: 1;\n    min-width: 0;\n    display: flex;\n    flex-direction: column;\n}\n.presenit-ready #presenit-stage {\n    flex: 1;\n    min-height: 0;\n    display: grid;\n    place-items: center;\n    overflow: hidden;\n    touch-action: pinch-zoom;\n}\n.presenit-ready #presenit-stage .presenit-deck {\n    width: var(--presenit-scaled-width);\n    height: var(--presenit-scaled-height);\n    position: relative;\n    overflow: clip;\n    background: transparent;\n    box-shadow: var(--presenit-ui-slide-shadow);\n}\n.presenit-ready #presenit-stage .presenit-slide {\n    position: absolute;\n    left: 0;\n    top: 0;\n    transform: scale(var(--presenit-scale));\n    transform-origin: top left;\n}\n.presenit-ready #presenit-stage .presenit-slide.is-current {\n    z-index: 1;\n}\n.presenit-ready #presenit-stage .presenit-slide:not(.is-current, .is-leaving) {\n    display: none;\n}\n.presenit-idle:not(.is-presenter) #presenit-stage,\n.presenit-idle:not(.is-presenter) #presenit-stage *,\n.is-laser #presenit-stage .presenit-slide.is-current,\n.is-laser #presenit-stage .presenit-slide.is-current * {\n    cursor: none;\n}\n\n/* ------------------------------------------------------------------ */\n/* Floating toolbar                                                   */\n/* ------------------------------------------------------------------ */\n.presenit-toolbar {\n    position: fixed;\n    left: 50%;\n    bottom: max(16px, env(safe-area-inset-bottom));\n    z-index: 20;\n    display: flex;\n    align-items: center;\n    gap: 2px;\n    padding: 4px;\n    border: 1px solid var(--presenit-ui-line);\n    border-radius: 999px;\n    color: var(--presenit-ui-text);\n    background: var(--presenit-ui-surface);\n    box-shadow: var(--presenit-ui-shadow);\n    -webkit-backdrop-filter: blur(16px) saturate(1.4);\n    backdrop-filter: blur(16px) saturate(1.4);\n    opacity: 0;\n    translate: -50% 10px;\n    pointer-events: none;\n    transition:\n        opacity 0.2s ease,\n        translate 0.2s ease;\n}\n.presenit-toolbar-shown .presenit-toolbar,\n.presenit-toolbar:has(:focus-visible) {\n    opacity: 1;\n    translate: -50% 0;\n    pointer-events: auto;\n}\n.presenit-icon-button {\n    display: inline-grid;\n    place-items: center;\n    min-width: 40px;\n    min-height: 40px;\n    padding: 0;\n    border: 0;\n    border-radius: 999px;\n    background: transparent;\n    transition:\n        background-color 0.12s ease,\n        color 0.12s ease;\n}\n@media (hover: hover) {\n    .presenit-icon-button:hover {\n        background: var(--presenit-ui-hover);\n    }\n}\n.presenit-icon-button:active {\n    background: var(--presenit-ui-line);\n}\n.presenit-icon-button[aria-pressed=\"true\"] {\n    color: var(--presenit-ui-accent);\n    background: var(--presenit-ui-accent-soft);\n    box-shadow: inset 0 0 0 1.5px var(--presenit-ui-accent);\n}\n.presenit-icon-button[aria-disabled=\"true\"] {\n    opacity: 0.35;\n    cursor: default;\n}\n@media (hover: hover) {\n    .presenit-icon-button[aria-disabled=\"true\"]:hover {\n        background: transparent;\n    }\n}\n.presenit-separator {\n    align-self: stretch;\n    margin: 8px 4px;\n    border-left: 1px solid var(--presenit-ui-line);\n}\n.presenit-position {\n    /* Fixed size: the number and Reveal dots stay put from slide to slide. */\n    width: max(4.75rem, calc(var(--presenit-total-digits, 2) * 2ch + 2ch));\n    padding: 0 6px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    gap: 4px;\n    font-size: 14px;\n    line-height: 1;\n    font-variant-numeric: tabular-nums;\n    white-space: nowrap;\n}\n.presenit-steps {\n    height: 5px;\n    display: flex;\n    gap: 3px;\n    align-items: center;\n    color: var(--presenit-ui-muted);\n}\n.presenit-steps i {\n    width: 5px;\n    height: 5px;\n    border-radius: 50%;\n    background: currentColor;\n    opacity: 0.5;\n}\n.presenit-steps i.is-on {\n    background: var(--presenit-ui-accent);\n    opacity: 1;\n}\n.presenit-steps-text {\n    font-size: 10px;\n    line-height: 5px;\n}\n\n/* Menu: a group of buttons in a popover above its trigger. */\n.presenit-menu {\n    position: fixed;\n    inset: auto;\n    margin: 0;\n    min-width: 232px;\n    padding: 6px;\n    border: 1px solid var(--presenit-ui-line);\n    border-radius: 14px;\n    color: var(--presenit-ui-text);\n    background: var(--presenit-ui-surface);\n    box-shadow: var(--presenit-ui-shadow);\n    -webkit-backdrop-filter: blur(20px) saturate(1.4);\n    backdrop-filter: blur(20px) saturate(1.4);\n}\n@media (prefers-reduced-motion: no-preference) {\n    .presenit-menu:popover-open {\n        animation: presenit-pop 0.14s ease-out;\n    }\n}\n@keyframes presenit-pop {\n    from {\n        opacity: 0;\n        translate: 0 4px;\n    }\n}\n.presenit-menu-item {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    width: 100%;\n    min-height: 38px;\n    padding: 0 10px;\n    border: 0;\n    border-radius: 9px;\n    font-size: 14px;\n    text-align: left;\n    background: transparent;\n}\n@media (hover: hover) {\n    .presenit-menu-item:hover {\n        background: var(--presenit-ui-hover);\n    }\n}\n.presenit-menu-item .presenit-icon {\n    width: 18px;\n    height: 18px;\n    color: var(--presenit-ui-muted);\n}\n.presenit-menu-item[aria-pressed=\"true\"] {\n    color: var(--presenit-ui-accent);\n}\n.presenit-menu-item[aria-pressed=\"true\"] .presenit-icon {\n    color: currentColor;\n}\n.presenit-menu-item span {\n    flex: 1;\n}\nkbd {\n    min-width: 1.5em;\n    padding: 2px 5px;\n    border: 1px solid var(--presenit-ui-line);\n    border-radius: 5px;\n    font-family: inherit;\n    font-size: 11px;\n    font-weight: 500;\n    line-height: 1.2;\n    text-align: center;\n    color: var(--presenit-ui-muted);\n}\n\n/* Tooltip: in the top layer so it also clears the open menu. */\n.presenit-tooltip:popover-open {\n    display: flex;\n}\n.presenit-tooltip {\n    position: fixed;\n    inset: auto;\n    margin: 0;\n    padding: 5px 8px;\n    align-items: center;\n    gap: 8px;\n    border: 1px solid transparent;\n    border-radius: 7px;\n    font-size: 12px;\n    line-height: 1.2;\n    white-space: nowrap;\n    pointer-events: none;\n    color: var(--presenit-ui-tip-text);\n    background: var(--presenit-ui-tip-bg);\n    box-shadow: var(--presenit-ui-shadow);\n}\n.presenit-tooltip kbd {\n    border-color: currentColor;\n    color: inherit;\n    opacity: 0.75;\n}\n\n/* Status messages appear as a short-lived toast. */\n.presenit-status {\n    position: fixed;\n    left: 50%;\n    bottom: 80px;\n    translate: -50% 0;\n    z-index: 25;\n    max-width: min(32rem, calc(100vw - 32px));\n    margin: 0;\n    padding: 9px 14px;\n    border: 1px solid var(--presenit-ui-line);\n    border-radius: 10px;\n    font-size: 13px;\n    line-height: 1.5;\n    background: var(--presenit-ui-surface);\n    box-shadow: var(--presenit-ui-shadow);\n    -webkit-backdrop-filter: blur(16px);\n    backdrop-filter: blur(16px);\n}\n.presenit-status:empty {\n    display: none;\n}\n\n/* ------------------------------------------------------------------ */\n/* Overview                                                           */\n/* ------------------------------------------------------------------ */\n.presenit-overview {\n    width: min(1200px, calc(100vw - 32px));\n    max-width: none;\n    max-height: calc(100dvh - 48px);\n    padding: 0;\n    border: 1px solid var(--presenit-ui-line);\n    border-radius: 16px;\n    color: var(--presenit-ui-text);\n    background: var(--presenit-ui-panel);\n    box-shadow: var(--presenit-ui-shadow);\n    overscroll-behavior: contain;\n}\n.presenit-overview[open] {\n    display: flex;\n    flex-direction: column;\n}\n.presenit-overview::backdrop {\n    background: var(--presenit-ui-scrim);\n    -webkit-backdrop-filter: blur(6px);\n    backdrop-filter: blur(6px);\n}\n.presenit-overview header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 8px 8px 8px 20px;\n    border-bottom: 1px solid var(--presenit-ui-line);\n}\n.presenit-overview h2 {\n    margin: 0;\n    font-size: 15px;\n    font-weight: 600;\n}\n.presenit-grid {\n    flex: 1;\n    min-height: 0;\n    overflow: auto;\n    overscroll-behavior: contain;\n    padding: 20px;\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n    gap: 20px 16px;\n}\n.presenit-grid > button {\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n    min-width: 0;\n    padding: 0;\n    border: 0;\n    border-radius: 8px;\n    text-align: left;\n    background: transparent;\n}\n.presenit-thumb {\n    width: 100%;\n    aspect-ratio: var(--presenit-aspect);\n    overflow: hidden;\n    border-radius: 6px;\n    outline: 1px solid var(--presenit-ui-line);\n    transition: outline-color 0.12s ease;\n}\n@media (hover: hover) {\n    .presenit-grid > button:hover .presenit-thumb {\n        outline: 2px solid var(--presenit-ui-muted);\n    }\n}\n.presenit-grid > button[aria-current=\"true\"] .presenit-thumb {\n    outline: 2px solid var(--presenit-ui-accent);\n    outline-offset: 2px;\n}\n.presenit-thumb-label {\n    display: flex;\n    gap: 8px;\n    min-width: 0;\n    font-size: 13px;\n    color: var(--presenit-ui-muted);\n}\n.presenit-thumb-label span {\n    min-width: 0;\n    overflow: hidden;\n    white-space: nowrap;\n    text-overflow: ellipsis;\n}\n.presenit-thumb-label b {\n    font-weight: 600;\n    font-variant-numeric: tabular-nums;\n    color: var(--presenit-ui-text);\n}\n.presenit-grid > button[aria-current=\"true\"] .presenit-thumb-label b {\n    color: var(--presenit-ui-accent);\n}\n.presenit-preview > .presenit-slide,\n.presenit-thumb > .presenit-slide {\n    transform: scale(var(--presenit-scale));\n    transform-origin: top left;\n    pointer-events: none;\n}\n.presenit-thumb .is-concealed {\n    visibility: visible;\n    opacity: 1;\n}\n\n/* ------------------------------------------------------------------ */\n/* Presenter: controls stay docked and visible.                       */\n/* ------------------------------------------------------------------ */\n.is-presenter .presenit-main {\n    padding: 16px;\n    gap: 12px;\n}\n.is-presenter #presenit-stage {\n    touch-action: pan-y pinch-zoom;\n}\n.is-presenter .presenit-toolbar {\n    position: static;\n    align-self: center;\n    translate: none;\n    opacity: 1;\n    pointer-events: auto;\n    background: var(--presenit-ui-panel);\n    box-shadow: none;\n    -webkit-backdrop-filter: none;\n    backdrop-filter: none;\n}\n.presenit-presenter {\n    width: clamp(300px, 30vw, 440px);\n    flex: none;\n    overflow: auto;\n    padding: 20px;\n    box-sizing: border-box;\n    display: flex;\n    flex-direction: column;\n    gap: 22px;\n    border-left: 1px solid var(--presenit-ui-line);\n    background: var(--presenit-ui-panel);\n}\n.presenit-ui-title {\n    margin: 0;\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--presenit-ui-muted);\n}\n.presenit-label {\n    display: block;\n    margin: 0 0 8px;\n    font-size: 12px;\n    font-weight: 600;\n    letter-spacing: 0.02em;\n    color: var(--presenit-ui-muted);\n}\n.presenit-timer-card {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    padding: 14px 14px 14px 16px;\n    border: 1px solid var(--presenit-ui-line);\n    border-radius: 12px;\n    background: var(--presenit-ui-raised);\n}\n.presenit-timer-text .presenit-label {\n    margin-bottom: 4px;\n}\n.presenit-timer {\n    display: block;\n    font-size: 2.4rem;\n    font-weight: 600;\n    line-height: 1.1;\n    letter-spacing: 0.01em;\n    font-variant-numeric: tabular-nums;\n}\n.presenit-timer.is-paused {\n    color: var(--presenit-ui-muted);\n}\n.presenit-actions {\n    display: flex;\n    gap: 4px;\n}\n.presenit-actions .presenit-icon-button {\n    border: 1px solid var(--presenit-ui-line);\n}\n.presenit-preview {\n    width: 100%;\n    aspect-ratio: var(--presenit-aspect);\n    overflow: hidden;\n    border-radius: 8px;\n    outline: 1px solid var(--presenit-ui-line);\n    background: var(--presenit-ui-raised);\n}\n.presenit-preview-end {\n    height: 100%;\n    margin: 0;\n    display: grid;\n    place-items: center;\n    font-size: 14px;\n    color: var(--presenit-ui-muted);\n}\n.presenit-notes {\n    margin: 0;\n    white-space: pre-wrap;\n    font-size: 17px;\n    line-height: 1.7;\n}\n.presenit-notes.is-empty {\n    font-size: 14px;\n    color: var(--presenit-ui-muted);\n}\n\n/* ------------------------------------------------------------------ */\n/* Blackout and laser                                                 */\n/* ------------------------------------------------------------------ */\n.presenit-blackout {\n    position: fixed;\n    inset: 0;\n    z-index: 15;\n    background: black;\n    cursor: none;\n}\n.presenit-laser {\n    position: fixed;\n    z-index: 30;\n    width: 12px;\n    height: 12px;\n    border: 2px solid white;\n    border-radius: 50%;\n    background: #e72e39;\n    box-shadow: 0 0 10px 2px #e72e39b3;\n    translate: -50% -50%;\n    pointer-events: none;\n}\n.is-blackout .presenit-toolbar,\n.is-blackout .presenit-status,\n.is-blackout .presenit-laser {\n    visibility: hidden;\n}\n\n/* Reveal */\n.presenit-slide [data-presenit-at] {\n    transition: opacity var(--presenit-fragment-duration, 0.3s) ease;\n}\n.presenit-slide .is-concealed {\n    visibility: hidden;\n    opacity: 0;\n}\n\n@media (pointer: coarse) {\n    .presenit-icon-button {\n        min-width: 44px;\n        min-height: 44px;\n    }\n}\n@media (max-width: 420px) {\n    .presenit-toolbar {\n        gap: 0;\n        padding: 3px;\n    }\n    .presenit-position {\n        width: max(3.75rem, calc(var(--presenit-total-digits, 2) * 2ch + 2ch));\n        padding: 0 2px;\n    }\n    .presenit-separator {\n        margin-inline: 2px;\n    }\n}\n@media (max-width: 760px) {\n    .presenit-ready.is-presenter body {\n        height: auto;\n        overflow: auto;\n    }\n    .is-presenter .presenit-layout {\n        flex-direction: column;\n        height: auto;\n    }\n    .is-presenter .presenit-main {\n        flex: none;\n    }\n    .is-presenter #presenit-stage {\n        flex: none;\n        aspect-ratio: var(--presenit-aspect);\n        max-height: 70dvh;\n    }\n    .presenit-presenter {\n        width: auto;\n        overflow: visible;\n        border-left: 0;\n        border-top: 1px solid var(--presenit-ui-line);\n    }\n}\n@media (prefers-reduced-motion: reduce) {\n    .presenit-toolbar {\n        translate: -50% 0;\n        transition: opacity 0.12s linear;\n    }\n    .presenit-slide [data-presenit-at] {\n        transition: none;\n    }\n}\n@media (forced-colors: active) {\n    .presenit-icon-button[aria-pressed=\"true\"] {\n        outline: 2px solid Highlight;\n    }\n    .presenit-steps i.is-on {\n        background: Highlight;\n    }\n}\n\n/* ------------------------------------------------------------------ */\n/* Print: every slide and Reveal, one per page, without Viewer chrome. */\n/* ------------------------------------------------------------------ */\n@media print {\n    /* Transitions outrank !important, so a Reveal fade would otherwise start\n       when the print media applies and could be captured half-transparent. */\n    *,\n    *::before,\n    *::after {\n        transition: none !important;\n    }\n    html,\n    body {\n        height: auto !important;\n        min-height: 0 !important;\n        overflow: visible !important;\n        background: white !important;\n        margin: 0 !important;\n        padding: 0 !important;\n    }\n    .presenit-layout,\n    .presenit-main,\n    #presenit-stage {\n        display: block !important;\n        height: auto !important;\n        padding: 0 !important;\n        overflow: visible !important;\n        visibility: visible !important;\n        animation: none !important;\n    }\n    .presenit-ready #presenit-stage .presenit-deck {\n        width: auto;\n        height: auto;\n        overflow: visible;\n        box-shadow: none;\n    }\n    .presenit-ready #presenit-stage .presenit-slide {\n        display: flex !important;\n        position: relative !important;\n        transform: none !important;\n        translate: none !important;\n        opacity: 1 !important;\n        margin: 0 !important;\n        border: 0 !important;\n        break-after: page;\n        break-inside: avoid;\n        print-color-adjust: exact;\n        -webkit-print-color-adjust: exact;\n    }\n    #presenit-stage .presenit-slide:last-child {\n        break-after: auto;\n    }\n    .presenit-slide .is-concealed {\n        visibility: visible !important;\n        opacity: 1 !important;\n    }\n    .presenit-toolbar,\n    .presenit-menu,\n    .presenit-tooltip,\n    .presenit-presenter,\n    .presenit-overview,\n    .presenit-status,\n    .presenit-laser,\n    .presenit-blackout,\n    noscript {\n        display: none !important;\n    }\n    .katex .katex-mathml {\n        display: none;\n    }\n}\n";
